"use client";

import { useMailStore } from "@/stores/use-mail-store";
import { Sidebar } from "@/components/sidebar";
import { ThreadList } from "@/components/thread-list";
import { EmailDetail } from "@/components/email-detail";
import { AIInboxBrief } from "@/components/ai-brief";
import { useMounted } from "@/hooks/use-mounted";
import { Menu } from "lucide-react";
import { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";

export default function Home() {
  const isMounted = useMounted();
  const { selectedEmailId, selectEmail } = useMailStore();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Prevent SSR flash
  if (!isMounted) {
    return <div className="h-screen bg-zinc-50 dark:bg-zinc-950" />;
  }

  return (
    <div className="flex h-screen overflow-hidden bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 selection:bg-blue-200 dark:selection:bg-blue-900">
      
      {/* Mobile Header (Visible only on small screens) */}
      <div className="md:hidden fixed top-0 w-full h-14 bg-white/80 dark:bg-zinc-950/80 backdrop-blur-md border-b z-50 flex items-center px-4 justify-between">
        <button onClick={() => setMobileMenuOpen(true)} className="p-2 -ml-2 text-zinc-600 dark:text-zinc-400">
          <Menu className="w-5 h-5" />
        </button>
        <span className="font-semibold text-sm">InboxOS</span>
        <div className="w-9" /> {/* Spacer */}
      </div>

      {/* Sidebar Desktop */}
      <div className="hidden md:block shrink-0 z-20">
        <Sidebar />
      </div>

      {/* Sidebar Mobile Drawer */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <>
            <motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              onClick={() => setMobileMenuOpen(false)}
              className="md:hidden fixed inset-0 bg-black/40 backdrop-blur-sm z-50"
            />
            <motion.div 
              initial={{ x: "-100%" }} animate={{ x: 0 }} exit={{ x: "-100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="md:hidden fixed inset-y-0 left-0 w-[280px] bg-white dark:bg-zinc-950 z-50 shadow-2xl"
            >
              <Sidebar onNavigate={() => setMobileMenuOpen(false)} />
            </motion.div>
          </>
        )}
      </AnimatePresence>

      {/* Main Content Area (Thread List + Detail) */}
      <div className="flex flex-1 overflow-hidden relative pt-14 md:pt-0">
        
        {/* Thread List Pane */}
        <div className={`
          flex flex-col h-full shrink-0 border-r border-zinc-200 dark:border-zinc-800/50 bg-zinc-50/30 dark:bg-zinc-950/50
          absolute inset-0 md:relative md:w-[360px] lg:w-[400px] z-10
          transition-transform duration-300 ease-in-out
          ${selectedEmailId ? '-translate-x-full md:translate-x-0' : 'translate-x-0'}
        `}>
          <AIInboxBrief />
          <ThreadList />
        </div>

        {/* Email Detail Pane */}
        <div className={`
          flex-1 h-full bg-white dark:bg-zinc-950 z-20 absolute inset-0 md:relative
          transition-transform duration-300 ease-in-out
          ${selectedEmailId ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        `}>
          <EmailDetail onBack={() => selectEmail(null)} />
        </div>

      </div>
    </div>
  );
}
